class Solution {
  public long minimumTotalDistance(List<Integer> robot, int[][] factory) {
    List<Integer> robots = new ArrayList<>(robot);
    Collections.sort(robots);
    int[][] factories = factory.clone();
    Arrays.sort(factories, (a, b) -> Integer.compare(a[0], b[0]));
    int n = robots.size();
    final long INF = Long.MAX_VALUE / 4;
    // dp[i]: cheapest way to repair the first i robots using the factories processed so far
    long[] dp = new long[n + 1];
    Arrays.fill(dp, INF);
    dp[0] = 0;
    for (int[] f : factories) {
      long[] next = dp.clone();
      for (int i = 1; i <= n; i++) {
        long cost = 0;
        for (int j = 1; j <= Math.min(f[1], i); j++) {
          cost += Math.abs((long) robots.get(i - j) - f[0]);
          if (dp[i - j] < INF) next[i] = Math.min(next[i], dp[i - j] + cost);
        }
      }
      dp = next;
    }
    return dp[n];
  }
}
